/* Integração opt-in dentro do aplicativo completo. Sem conexão ao abrir a tela. */
(()=>{'use strict';const $=id=>document.getElementById(id),panel=document.createElement('details');panel.innerHTML=`<summary>RDO no Supabase de homologação</summary><p>Configure um projeto de testes com SQL 31. O envio é explícito, usa vínculos por UUID e preserva a base local. A aprovação remota confirma a frequência na mesma transação; divergências são bloqueadas.</p><label>URL do projeto de homologação<input id="mrs-url" type="url" placeholder="https://seu-projeto.supabase.co"></label><label>Chave pública publishable/anon<input id="mrs-key" autocomplete="off"></label><label>Empresa (UUID)<input id="mrs-company"></label><label>E-mail<input id="mrs-email" type="email" autocomplete="username"></label><label>Senha<input id="mrs-password" type="password" autocomplete="current-password"></label><button id="mrs-login" type="button">Autenticar homologação</button><button id="mrs-local" type="button">Carregar vínculos locais, sem conectar</button><fieldset id="mrs-fields" disabled><label>Funcionário local<select id="mrs-local-person"></select></label><label>Funcionário remoto<select id="mrs-remote-person"></select></label><button id="mrs-bind-person" type="button">Vincular funcionário</button><label>Obra local<select id="mrs-local-work"></select></label><label>Obra remota<select id="mrs-remote-work"></select></label><button id="mrs-bind-work" type="button">Vincular obra</button><label>RDO local<select id="mrs-rdo"></select></label><button id="mrs-refresh" type="button">Atualizar RDOs locais</button><label>Revisão remota esperada (0 para novo)<input id="mrs-revision" type="number" min="0" step="1" value="0"></label><button id="mrs-query" type="button">Consultar revisão remota</button><button id="mrs-send" type="button">Enviar este RDO de homologação</button><label>Motivo da reabertura remota<input id="mrs-reason" minlength="5" maxlength="500"></label><button id="mrs-reopen" type="button">Reabrir RDO remoto com histórico</button></fieldset><h3>Fila local de envios</h3><p>Preparar não envia dados. Envios só ocorrem após autenticação e comando explícito. Alterações no RDO ou nos vínculos exigem nova conferência.</p><button id="mrs-queue" type="button">Guardar este envio pendente</button><button id="mrs-queue-refresh" type="button">Atualizar fila</button><button id="mrs-queue-send" type="button">Enviar pendentes deste projeto/empresa</button><div style="overflow:auto"><table><thead><tr><th>RDO</th><th>Situação</th><th>Tentativas</th><th>Resultado</th></tr></thead><tbody id="mrs-queue-rows"></tbody></table></div><p id="mrs-status" role="status">Desconectado. Nenhum dado foi enviado.</p>`;$('mj-dialog').append(panel);
let client=null,company=null,mapping=null,key=null,busy=false,context=null;const say=s=>$('mrs-status').textContent=s;
const fill=(id,rows,label)=>{const el=$(id);el.replaceChildren(new Option('Selecione',''));for(const row of rows)el.add(new Option(label(row),String(row.id)));};
const check=r=>{if(r.error)throw r.error;return r.data;};const run=fn=>async()=>{if(busy)return;busy=true;try{await fn();}catch(e){say('Erro: '+e.message);}finally{busy=false;}};
const refresh=()=>{const list=getDb();fill('mrs-rdo',list,x=>`${x.num||x.id} · ${x.obra} · ${x.data} · ${x.status}`);};
async function sdk(){if(globalThis.supabase)return globalThis.supabase;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.onload=resolve;s.onerror=()=>reject(Error('Não foi possível carregar o cliente Supabase'));document.head.append(s);});return globalThis.supabase;}
$('mrs-login').onclick=run(async()=>{client=null;company=null;$('mrs-fields').disabled=true;const endpoint=new URL($('mrs-url').value);if(endpoint.protocol!=='https:'||!endpoint.hostname.endsWith('.supabase.co')||endpoint.username||endpoint.password||endpoint.search||endpoint.hash||endpoint.pathname!=='/')throw Error('Informe a URL HTTPS do projeto de homologação');const id=$('mrs-company').value.trim();if(!MartinsRdoRemoto.uuid(id))throw Error('Empresa inválida');const publicKey=$('mrs-key').value.trim();let anon=false;if(publicKey.startsWith('eyJ')){try{anon=JSON.parse(atob(publicKey.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role==='anon';}catch{}}if(!publicKey.startsWith('sb_publishable_')&&!anon)throw Error('Use somente chave pública publishable ou anon; chaves secretas não são aceitas');const api=await sdk(),candidate=api.createClient(endpoint.origin,publicKey);const password=$('mrs-password').value;let auth;try{auth=await candidate.auth.signInWithPassword({email:$('mrs-email').value.trim(),password});}finally{$('mrs-password').value='';}check(auth);if(!check(await candidate.rpc('martins_rh_admin',{p_empresa:id})))throw Error('Administrador da empresa não autorizado');const [people,works]=await Promise.all([candidate.from('martins_funcionarios').select('id,nome').eq('empresa_id',id).eq('ativo',true).order('nome').limit(1000),candidate.from('martins_obras').select('id,nome').eq('empresa_id',id).order('nome').limit(1000)]);fill('mrs-remote-person',check(people),x=>x.nome);fill('mrs-remote-work',check(works),x=>x.nome);fill('mrs-local-person',getColaboradoresDb(),x=>x.nome);fill('mrs-local-work',Object.keys(dadosObras).map(x=>({id:x})),x=>x.id);key='martins_vinculos_remotos_v1_'+endpoint.hostname+'_'+id;mapping=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});client=candidate;company=id;context=MartinsFilaRdo.scope(endpoint.origin,id);refresh();renderQueue();$('mrs-fields').disabled=false;say('Autenticado. Vincule IDs antes de enviar. Listas remotas limitadas a 1000 cadastros.');});
function requireContext(online=false){if(typeof MartinsPersistenciaRdo!=='undefined')MartinsPersistenciaRdo.guard(localStorage,'cm_gestao_rdo_v5_db');if(!context)throw Error('Carregue o projeto e empresa');const visible=MartinsFilaRdo.scope($('mrs-url').value,$('mrs-company').value.trim());if(visible.key!==context.key)throw Error('Projeto ou empresa mudou; carregue os vínculos e autentique novamente');if(online&&!client)throw Error('Autentique neste projeto antes de enviar');}
function bind(localId,remoteId,type){requireContext(true);if(!client)throw Error('Autentique primeiro');if(!$(localId).value||!MartinsRdoRemoto.uuid($(remoteId).value))throw Error('Selecione os dois cadastros');const before=localStorage.getItem(key),next=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});if(Object.entries(next[type]).some(([local,remote])=>local!==$(localId).value&&remote===$(remoteId).value))throw Error('Este UUID já está vinculado a outro cadastro local');next[type][$(localId).value]=$(remoteId).value;MartinsJornada.write(localStorage,key,next,before);mapping=next;say('Vínculo salvo neste navegador. Nenhum cadastro foi criado no servidor.');}
$('mrs-bind-person').onclick=run(()=>bind('mrs-local-person','mrs-remote-person','employees'));$('mrs-bind-work').onclick=run(()=>bind('mrs-local-work','mrs-remote-work','works'));$('mrs-refresh').onclick=run(refresh);
$('mrs-rdo').onchange=()=>{$('mrs-revision').value=mapping?.revisions?.[$('mrs-rdo').value]||0;};
$('mrs-query').onclick=run(async()=>{requireContext(true);if(!client||!$('mrs-rdo').value)throw Error('Autentique e selecione um RDO');const rows=check(await client.from('martins_rdos_integrados').select('revisao,status,atualizado_em').eq('empresa_id',company).eq('id_local',$('mrs-rdo').value));say(rows.length?`Remoto: revisão ${rows[0].revisao}, ${rows[0].status}. Compare antes de informar a revisão esperada.`:'Documento ainda não existe no servidor.');});
$('mrs-send').onclick=run(async()=>{requireContext(true);if(!client)throw Error('Autentique primeiro');const rdo=getDb().find(x=>String(x.id)===$('mrs-rdo').value);if(!rdo)throw Error('Selecione um RDO atual');const args=MartinsRdoRemoto.prepare(rdo,getColaboradoresDb(),mapping,company,Number($('mrs-revision').value));const result=await MartinsRdoRemoto.send(client,args);const before=localStorage.getItem(key),next=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});next.revisions[rdo.id]=result.revisao;try{MartinsJornada.write(localStorage,key,next,before);}catch(e){say('Servidor confirmou revisão '+result.revisao+', mas o vínculo local não foi salvo: '+e.message);return;}mapping=next;$('mrs-revision').value=result.revisao;say(`RDO confirmado no servidor: revisão ${result.revisao}${result.reenvio?' (reenvio sem duplicidade)':''}. Conteúdo local preservado.`);});
$('mrs-reopen').onclick=run(async()=>{requireContext(true);if(!client||!$('mrs-rdo').value)throw Error('Autentique e selecione um RDO');const reason=$('mrs-reason').value.trim();if(reason.length<5)throw Error('Descreva o motivo da reabertura');const revision=check(await client.rpc('martins_reabrir_rdo_integrado',{p_empresa:company,p_id_local:$('mrs-rdo').value,p_revisao_esperada:Number($('mrs-revision').value),p_motivo:reason}));const before=localStorage.getItem(key),next=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});next.revisions[$('mrs-rdo').value]=revision;MartinsJornada.write(localStorage,key,next,before);mapping=next;$('mrs-revision').value=revision;say('RDO remoto reaberto com histórico; frequência preservada. Para editar o conteúdo local, use a reabertura autorizada no RDO original.');});
function renderQueue(){if(!context)throw Error('Carregue o contexto local ou autentique');$('mrs-queue-rows').replaceChildren();for(const job of MartinsFilaRdo.read(localStorage,context)){const tr=document.createElement('tr');for(const value of [job.payload.p_id_local,job.status,job.attempts,job.lastError||(job.receipt?'Revisão '+job.receipt.revisao:'Aguardando comando de envio')]){const td=document.createElement('td');td.textContent=String(value);tr.append(td);}$('mrs-queue-rows').append(tr);}}
$('mrs-local').onclick=run(()=>{const nextContext=MartinsFilaRdo.scope($('mrs-url').value,$('mrs-company').value.trim());client=null;company=nextContext.company;context=nextContext;key='martins_vinculos_remotos_v1_'+new URL(context.endpoint).hostname+'_'+company;mapping=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});refresh();$('mrs-fields').disabled=false;renderQueue();say('Vínculos locais carregados. Nenhuma conexão foi iniciada. Envio remoto exige autenticação.');});
$('mrs-queue-refresh').onclick=run(renderQueue);
$('mrs-queue').onclick=run(async()=>{requireContext(false);if(!context||!mapping)throw Error('Carregue os vínculos locais ou autentique');const rdo=getDb().find(x=>String(x.id)===$('mrs-rdo').value);if(!rdo)throw Error('Selecione RDO atual');const payload=MartinsRdoRemoto.prepare(rdo,getColaboradoresDb(),mapping,company,Number($('mrs-revision').value));const job=await MartinsFilaRdo.enqueue(localStorage,context,payload);renderQueue();say('Envio registrado na fila: '+job.status+'. Nenhum dado foi enviado nesta preparação.');});
$('mrs-queue-send').onclick=run(async()=>{requireContext(true);if(!client||!context||company!==context.company)throw Error('Autentique neste projeto e empresa antes de enviar');const execute=()=>MartinsFilaRdo.drain(localStorage,context,args=>MartinsRdoRemoto.send(client,args),job=>{if(typeof MartinsPersistenciaRdo!=='undefined')MartinsPersistenciaRdo.guard(localStorage,'cm_gestao_rdo_v5_db');const current=getDb().find(x=>String(x.id)===job.payload.p_id_local);if(!current)throw Error('Conflito: RDO local removido');const freshMapping=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});return MartinsRdoRemoto.prepare(current,getColaboradoresDb(),freshMapping,company,job.payload.p_revisao_esperada);},{onProgress:()=>renderQueue()});const result=navigator.locks?await navigator.locks.request(context.key,execute):await execute();const before=localStorage.getItem(key),next=MartinsJornada.read(localStorage,key,{employees:{},works:{},revisions:{}});for(const job of MartinsFilaRdo.read(localStorage,context).filter(x=>x.status==='enviado'))next.revisions[job.payload.p_id_local]=Math.max(next.revisions[job.payload.p_id_local]||0,job.receipt.revisao);MartinsJornada.write(localStorage,key,next,before);mapping=next;$('mrs-revision').value=next.revisions[$('mrs-rdo').value]||0;renderQueue();say(result.sent+' enviado(s), '+result.failed+' falha(s), '+result.conflicts+' conflito(s). Nenhum conflito foi sobrescrito.');});
})();
